import React, { useState } from 'react';
import axios from 'axios';
import { useNavigate, Link } from 'react-router-dom';
import { FaUserShield, FaUser, FaEnvelope, FaLock, FaEye, FaEyeSlash, FaKey } from 'react-icons/fa';
import styles from './styles.module.css';

const AdminSignup = () => {
  const [admin, setAdmin] = useState({ name: '', email: '', password: '', signupCode: '' });
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setSuccess('');
    setLoading(true);
    try {
      await axios.post(`${process.env.REACT_APP_API_URL}/auth/admin_signup`, admin);
      navigate('/admin/verify-pending', { state: { email: admin.email } });
    } catch (error) {
      setError(error.response?.data?.message || error.message || "Signup failed");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className={styles.page}>
      <div className={styles.card}>
        <div className={styles.banner}>
          <div className={styles.bannerIcon}><FaUserShield /></div>
          <span className={styles.bannerTag}>Admin Portal</span>
          <h1 className={styles.bannerTitle}>Create Your Account</h1>
          <p className={styles.bannerSubtitle}>Register a new administrator account.</p>
        </div>

        <form onSubmit={handleSubmit} className={styles.form}>
          {error && <div className={styles.error}>{error}</div>}
          {success && <div className={styles.success}>{success}</div>}

          <div className={styles.inputGroup}>
            <FaUser className={styles.inputIcon} />
            <input
              type="text"
              placeholder="Name"
              className={styles.input}
              value={admin.name}
              onChange={(e) => setAdmin({ ...admin, name: e.target.value })}
              required
            />
          </div>

          <div className={styles.inputGroup}>
            <FaEnvelope className={styles.inputIcon} />
            <input
              type="email"
              placeholder="Email"
              className={styles.input}
              value={admin.email}
              onChange={(e) => setAdmin({ ...admin, email: e.target.value })}
              required
            />
          </div>

          <div className={styles.inputGroup}>
            <FaLock className={styles.inputIcon} />
            <input
              type={showPassword ? "text" : "password"}
              placeholder="Password"
              className={styles.input}
              value={admin.password}
              onChange={(e) => setAdmin({ ...admin, password: e.target.value })}
              required
              style={{ paddingRight: '40px' }}
            />
            <button type="button" onClick={() => setShowPassword(v => !v)} style={{ position: 'absolute', right: '12px', background: 'none', border: 'none', cursor: 'pointer', color: '#9ca3af', display: 'flex', alignItems: 'center', padding: 0 }}>
              {showPassword ? <FaEyeSlash /> : <FaEye />}
            </button>
          </div>

          <div className={styles.inputGroup}>
            <FaKey className={styles.inputIcon} />
            <input
              type="text"
              placeholder="Admin Signup Code"
              className={styles.input}
              value={admin.signupCode}
              onChange={(e) => setAdmin({ ...admin, signupCode: e.target.value })}
              required
            />
          </div>
          <p className={styles.switchText} style={{ marginTop: '-8px' }}>
            Ask your institution's system administrator for the signup code.
          </p>

          <button type="submit" className={styles.submitBtn} disabled={loading}>
            {loading ? <span className={styles.loader}></span> : "Register"}
          </button>

          <p className={styles.switchText}>
            Already have an account?{" "}
            <Link to="/admin/login" className={styles.switchLink}>Login here</Link>
          </p>
        </form>
      </div>
    </div>
  );
};

export default AdminSignup;
